import { useState, useEffect, useContext } from "react";
import api from "../api";
import { AuthContext } from "../contexts/AuthContext";
import { useNavigate } from "react-router-dom";

export default function AdminDashboard() {
  const [votingOpen, setVotingOpen] = useState(false);
  const [pendingUsers, setPendingUsers] = useState([]);
  const [candidates, setCandidates] = useState([]);
  const [logs, setLogs] = useState([]);
  const [reportHash, setReportHash] = useState("");
  const [results, setResults] = useState({}); // { position: [candidates...] }
  const [winners, setWinners] = useState({}); // { position: winnerCandidate }

  const [loading, setLoading] = useState(false); // general loader for initial fetch
  const [actionLoading, setActionLoading] = useState(false); // for button actions

  const { logout, token } = useContext(AuthContext);
  const navigate = useNavigate();

  // ---------------- Unified error handler ----------------
  const handleApiError = (err) => {
    console.error(err);
    // axios style error
    if (err?.response?.status === 401) {
      try { logout(); } catch (e) { /* ignore */ }
      navigate("/login");
    } else {
      // show server message if available
      const msg = err?.response?.data?.error || err?.message || "An error occurred";
      alert(msg);
    }
  };

  // ---------------- Backend API calls ----------------
  const fetchVotingState = async () => {
    try {
      const res = await api.get("/admin/voting-state");
      setVotingOpen(Boolean(res.data.votingOpen));
    } catch (err) {
      handleApiError(err);
    }
  };

  const fetchPendingUsers = async () => {
    try {
      const res = await api.get("/admin/pending-users");
      setPendingUsers(Array.isArray(res.data) ? res.data : []);
    } catch (err) {
      handleApiError(err);
    }
  };

  const fetchCandidates = async () => {
    try {
      const res = await api.get("/admin/candidates");
      setCandidates(Array.isArray(res.data) ? res.data : []);
    } catch (err) {
      handleApiError(err);
    }
  };

  const fetchLogs = async () => {
    try {
      const res = await api.get("/admin/logs");
      setLogs(Array.isArray(res.data) ? res.data : []);
    } catch (err) {
      handleApiError(err);
    }
  };

  const toggleVoting = async () => {
    setActionLoading(true);
    try {
      const res = await api.post("/admin/toggle-voting");
      setVotingOpen(Boolean(res.data.votingOpen));
      // Refresh logs so admin sees the toggle entry
      await fetchLogs();
    } catch (err) {
      handleApiError(err);
    } finally {
      setActionLoading(false);
    }
  };

  const approveUser = async (id) => {
    if (!window.confirm("Approve this user?")) return;
    setActionLoading(true);
    try {
      await api.post(`/admin/approve-user/${id}`);
      await fetchPendingUsers();
      await fetchLogs();
    } catch (err) {
      handleApiError(err);
    } finally {
      setActionLoading(false);
    }
  };

  const rejectUser = async (id) => {
    if (!window.confirm("Reject this user? This will delete the record.")) return;
    setActionLoading(true);
    try {
      await api.post(`/admin/reject-user/${id}`);
      await fetchPendingUsers();
      await fetchLogs();
    } catch (err) {
      handleApiError(err);
    } finally {
      setActionLoading(false);
    }
  };

  const generateReport = async () => {
    setActionLoading(true);
    try {
      const res = await api.post("/admin/generate-report");
      // backend returns { hash: '...' }
      if (res?.data?.hash) {
        setReportHash(res.data.hash);
      } else {
        setReportHash("");
        alert("Report generated but no hash was returned.");
      }
      await fetchLogs();
    } catch (err) {
      handleApiError(err);
    } finally {
      setActionLoading(false);
    }
  };

  const deleteCandidate = async (id) => {
    if (!window.confirm("Delete this candidate? This action is irreversible.")) return;
    setActionLoading(true);
    try {
      await api.delete(`/admin/candidates/${id}`);
      await fetchCandidates();
      await fetchLogs();
      // after delete, refresh results too
      await fetchResults();
    } catch (err) {
      handleApiError(err);
    } finally {
      setActionLoading(false);
    }
  };

  const fetchResults = async () => {
    try {
      const res = await api.get("/admin/results");
      // backend expected shape: { positionResults: {...}, winners: {...} }
      const pr = res?.data?.positionResults || {};
      const w = res?.data?.winners || {};
      setResults(pr);
      setWinners(w);
    } catch (err) {
      handleApiError(err);
      // keep previous results if fail
    }
  };

  // ---------------- Initial load ----------------
  useEffect(() => {
    if (!token) {
      navigate("/login");
      return;
    }

    let mounted = true;
    const init = async () => {
      setLoading(true);
      try {
        // parallelize initial reads
        await Promise.all([
          fetchVotingState(),
          fetchPendingUsers(),
          fetchCandidates(),
          fetchLogs(),
          fetchResults(),
        ]);
      } catch (err) {
        console.error("Initial load error:", err);
      } finally {
        if (mounted) setLoading(false);
      }
    };
    init();

    return () => { mounted = false; };
  }, [token, navigate]);

  // ---------------- JSX ----------------
  return (
    <div className="min-h-screen bg-gray-100">
      {/* Header */}
      <header className="bg-white shadow-md py-4 px-6 flex justify-between items-center">
        <div>
          <h1 className="text-2xl font-semibold">iVote Admin Dashboard</h1>
          <p className="text-sm text-gray-500">Administrator console</p>
        </div>
        <div className="flex items-center gap-3">
          <span className={`px-3 py-1 rounded text-sm ${votingOpen ? "bg-green-100 text-green-700" : "bg-red-100 text-red-700"}`}>
            {votingOpen ? "Voting: Open" : "Voting: Closed"}
          </span>
          <button
            onClick={() => { try { logout(); } catch (e) {} navigate("/login"); }}
            className="bg-red-600 text-white px-4 py-2 rounded hover:bg-red-700"
          >
            Logout
          </button>
        </div>
      </header>

      <main className="p-6 space-y-6">
        {/* Top controls */}
        <section className="flex items-center justify-between gap-4">
          <div className="flex gap-3">
            <button
              onClick={toggleVoting}
              disabled={actionLoading}
              className={`px-5 py-2 rounded-lg font-semibold text-white ${actionLoading ? "opacity-60 cursor-not-allowed" : (votingOpen ? "bg-red-600 hover:bg-red-700" : "bg-green-600 hover:bg-green-700")}`}
            >
              {actionLoading ? "Processing..." : votingOpen ? "Close Voting" : "Open Voting"}
            </button>

            <button
              onClick={generateReport}
              disabled={actionLoading}
              className={`px-5 py-2 rounded-lg font-semibold text-white ${actionLoading ? "opacity-60 cursor-not-allowed" : "bg-blue-600 hover:bg-blue-700"}`}
            >
              {actionLoading ? "Generating..." : "Generate Final Report"}
            </button>
          </div>

          <div className="text-right">
            <p className="text-sm text-gray-600">Status: {loading ? "Loading…" : "Ready"}</p>
            {reportHash && <p className="mt-1 text-xs text-gray-700">Report Hash: <span className="font-mono">{reportHash}</span></p>}
          </div>
        </section>

        {/* Pending Users */}
        <section className="bg-white p-6 rounded-xl shadow-md">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-lg font-semibold">Pending Voter Registrations</h2>
            <p className="text-sm text-gray-500">{pendingUsers.length} pending</p>
          </div>

          {pendingUsers.length === 0 ? (
            <p className="text-gray-500">No pending users.</p>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full table-auto border-collapse">
                <thead>
                  <tr className="text-left text-sm text-gray-600">
                    <th className="py-2 pr-4">Student Number</th>
                    <th className="py-2 pr-4">Name</th>
                    <th className="py-2 pr-4">Email</th>
                    <th className="py-2 pr-4">Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {pendingUsers.map((user) => (
                    <tr key={user.id} className="border-t">
                      <td className="py-3 pr-4">{user.studentNumber}</td>
                      <td className="py-3 pr-4">{user.name}</td>
                      <td className="py-3 pr-4">{user.email}</td>
                      <td className="py-3 pr-4 space-x-2">
                        <button
                          onClick={() => approveUser(user.id)}
                          disabled={actionLoading}
                          className={`px-3 py-1 rounded ${actionLoading ? "opacity-60" : "bg-green-600 text-white hover:bg-green-700"}`}
                        >
                          Approve
                        </button>
                        <button
                          onClick={() => rejectUser(user.id)}
                          disabled={actionLoading}
                          className={`px-3 py-1 rounded ${actionLoading ? "opacity-60" : "bg-red-600 text-white hover:bg-red-700"}`}
                        >
                          Reject
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </section>

        {/* Candidates */}
        <section className="bg-white p-6 rounded-xl shadow-md">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-lg font-semibold">Candidates</h2>
            <p className="text-sm text-gray-500">{candidates.length} total</p>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full table-auto border-collapse">
              <thead>
                <tr className="text-left text-sm text-gray-600">
                  <th className="py-2 pr-4">Name</th>
                  <th className="py-2 pr-4">Position</th>
                  <th className="py-2 pr-4">Party</th>
                  <th className="py-2 pr-4">Actions</th>
                </tr>
              </thead>
              <tbody>
                {candidates.map((c) => (
                  <tr key={c.id} className="border-t hover:bg-gray-50">
                    <td className="py-3 pr-4">{c.name}</td>
                    <td className="py-3 pr-4">{c.position}</td>
                    <td className="py-3 pr-4">{c.party || "-"}</td>
                    <td className="py-3 pr-4">
                      <button
                        onClick={() => deleteCandidate(c.id)}
                        disabled={actionLoading}
                        className={`px-3 py-1 rounded ${actionLoading ? "opacity-60" : "bg-red-600 text-white hover:bg-red-700"}`}
                      >
                        Delete
                      </button>
                    </td>
                  </tr>
                ))}
                {candidates.length === 0 && (
                  <tr><td colSpan={4} className="py-4 text-gray-500">No candidates available.</td></tr>
                )}
              </tbody>
            </table>
          </div>
        </section>

        {/* System Logs */}
        <section className="bg-white p-6 rounded-xl shadow-md">
          <h2 className="text-lg font-semibold mb-4">System Logs</h2>
          {logs.length === 0 ? (
            <p className="text-gray-500">No logs available.</p>
          ) : (
            <ul className="max-h-64 overflow-y-auto divide-y">
              {logs.map((log) => (
                <li key={log.id} className="py-3">
                  <div className="flex justify-between">
                    <div className="text-sm text-gray-800">{log.action}</div>
                    <div className="text-xs text-gray-500">{new Date(log.createdAt).toLocaleString()}</div>
                  </div>
                </li>
              ))}
            </ul>
          )}
        </section>

        {/* Election Results */}
        <section className="bg-white p-6 rounded-xl shadow-md">
          <h2 className="text-lg font-semibold mb-4">Election Results</h2>

          {(!results || Object.keys(results).length === 0) ? (
            <p className="text-gray-500">No results available yet.</p>
          ) : (
            Object.keys(results).map((pos) => {
              const candidatesForPos = results[pos] || [];
              const winner = winners?.[pos] || null;
              return (
                <div key={pos} className="mb-6">
                  <h3 className="font-semibold mb-2">{pos}</h3>
                  <div className="overflow-x-auto">
                    <table className="w-full table-auto">
                      <thead>
                        <tr className="text-left text-sm text-gray-600">
                          <th className="py-2 pr-4">Name</th>
                          <th className="py-2 pr-4">Party</th>
                          <th className="py-2 pr-4">Votes</th>
                          <th className="py-2 pr-4">Status</th>
                        </tr>
                      </thead>
                      <tbody>
                        {candidatesForPos.map((c) => (
                          <tr key={c.id} className="border-t hover:bg-gray-50">
                            <td className="py-3 pr-4">{c.name}</td>
                            <td className="py-3 pr-4">{c.party || "-"}</td>
                            <td className="py-3 pr-4">{c.votes}</td>
                            <td className="py-3 pr-4 font-semibold">
                              {winner && winner.id === c.id ? (
                                <span className="text-green-600">Winner</span>
                              ) : (
                                <span className="text-gray-500">—</span>
                              )}
                            </td>
                          </tr>
                        ))}
                        {candidatesForPos.length === 0 && (
                          <tr><td colSpan={4} className="py-4 text-gray-500">No candidates for this position.</td></tr>
                        )}
                      </tbody>
                    </table>
                  </div>
                </div>
              );
            })
          )}
        </section>

        {/* Footer / Reports */}
        <section className="bg-white p-6 rounded-xl shadow-md flex flex-col items-start space-y-3">
          <h2 className="text-lg font-semibold text-gray-800">Reports</h2>
          <div className="flex items-center gap-3">
            <button
              onClick={generateReport}
              disabled={actionLoading}
              className={`px-4 py-2 rounded ${actionLoading ? "opacity-60" : "bg-blue-600 text-white hover:bg-blue-700"}`}
            >
              {actionLoading ? "Processing..." : "Generate Final Report"}
            </button>
            {reportHash && <div className="text-sm text-gray-700">Cryptographic Hash: <span className="font-mono">{reportHash}</span></div>}
          </div>
        </section>
      </main>
    </div>
  );
}
